
from builtins import str
from builtins import object
import time
from threading import Thread
from robot.errors import ExecutionFailed
from robot.libraries.BuiltIn import BuiltIn
from robot.running.context import EXECUTION_CONTEXTS
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.rfrl.trs_e2e_fw.setup.config_handler import get_variables
from future import standard_library
standard_library.install_aliases()
logger = BackgroundLogger.Instance()
threads = {}


class KeywordUtils(object):
    """
    KeywordUtils class contain robot keyword utility.
    The class directly interact with robot execution context.

    """
    error = False
    fatal_error = False

    def __init__(self):
        pass

    @staticmethod
    def _get_context():
        """

        Returns:
            Robot keyword execution context

        """
        context = EXECUTION_CONTEXTS.current
        if context is None:
            logger.info('Cannot access execution context')
        return context

    @staticmethod
    def get_keywords_from_args(keywords):
        """

        Args:
            keywords (str) : keyword string

        Returns:
            keyword list

        """
        while 'AND' in keywords:
            index = keywords.index('AND')
            yield keywords[:index]
            keywords = keywords[index + 1:]
        yield keywords

    @staticmethod
    def get_keyword_handler(ctx, kw):
        """

        Args:
            ctx (str) : ctx value
            kw (str) : keyword value

        Returns:
            ctx Value

        """
        return ctx.namespace._kw_store.get_runner(kw)

    @staticmethod
    def get_keyword_library(ctx, kw):
        """

        Args:
            ctx (str) : ctx value
            kw (str) : keyword value

        Returns:
            ctx Value

        """
        return KeywordUtils.get_keyword_handler(ctx, kw).library.get_instance()

    @staticmethod
    def get_keyword_name(kw_string):
        """

        Args:
            kw_string (str) : keyword value

        Returns:
            keyword string

        """
        return (kw_string[0]).replace(' ', '_').lower()

    @staticmethod
    def get_keyword_arguments(context, keywords):
        """

        Args:
            context (str) : Robot Execution context
            keywords (str) : keyword as a string

        Returns:
            positional and named arg as tuple

        """
        positional, named = KeywordUtils.get_keyword_handler(context, keywords[0])._handler.resolve_arguments(
            keywords[1:], context.variables)
        return positional, named

    def run_keyword(self, *keywords):
        """

        Execute the keyword with its argument.

        Args:
            *keywords (str) :  keyword and its argument

        Returns:
            None

        """
        logger.info("Run keyword  {}".format(keywords))
        try:
            kw_name = KeywordUtils.get_keyword_name(keywords)
            context = KeywordUtils._get_context()
            positional, named = KeywordUtils.get_keyword_arguments(
                context, keywords)
            named = dict(named)
            getattr(KeywordUtils.get_keyword_library(
                context, keywords[0]), kw_name)(*positional, **named)
        except Exception as e:
            logger.error(
                "Got an exception form {} keyword ".format(keywords[0]))
            logger.error("Exception {} ".format(str(e)))
            if hasattr(e, "ROBOT_EXIT_ON_FAILURE") and e.ROBOT_EXIT_ON_FAILURE:
                KeywordUtils.fatal_error = True
            KeywordUtils.error = True

    def run_keywords(self, keywords):
        """

        The given command as argument will be executed in parallel threads.

        Args:
            keywords (str) : keywords in a string

        Returns:
            None

        """
        logger.info("Keywords are {}".format(list(keywords)))
        thread_index = 1
        for keyword in KeywordUtils.get_keywords_from_args(keywords):
            logger.info("KW  :: {}".format(keyword))
            thread = Thread(name="Thread_{0}_{1}".format(thread_index, str(keyword)), target=self.run_keyword,
                            args=keyword)
            thread.start()
            threads[thread.getName()] = thread
            thread_index += 1

        # waiting for all thread to finsh.
        while threads:
            threads.popitem()[1].join()
        logger.log_background_messages()
        time.sleep(5)
        if KeywordUtils.fatal_error:
            BuiltIn().fatal_error("Fatal error occurred during parallel kw execution")
        if KeywordUtils.error:
            BuiltIn().fail("Parallel Keyword execution failed")

    def continue_on_failure(self, continue_on_fail=False):
        """

        Args:
            continue_on_fail (Boolean) : True or False

        Returns:
            None

        """
        ExecutionFailed.continue_on_failure = continue_on_fail


def run_keywords_in_parallel(*keywords):
    """Executes all the given keywords in a parallel.


    By default all arguments are expected to be passed to the keyword.
    Optional arguments must be passed as named argument.

    The keywords are executed so that the first argument is the first
    keyword and proceeding arguments until the first ``AND`` are arguments
    to it. First argument after the first ``AND`` is the second keyword and
    proceeding arguments until the next ``AND`` are its arguments. And so on.

    Currently supports only framework keywords.

    Examples:
    Run Keywords In Parallel |	Setup Ems | config_device=netact_1042 | AND | Setup Oamops
    Run Keywords In Parallel |	Teardown EMS | config_device=netact_1042 | AND | Teardown Oamops
    """
    KeywordUtils().run_keywords(keywords)


def continue_keyword_execution_on_failure(continue_on_failure=False):
    """
    This keyword can be used to continue/stop the execution of the current test case if a keyword failed during execution

    | *Arguments:* | *Description* |
    | continue_on_failure | This is a flag (takes boolean value) which tells whether to continue or stop the execution |
    |  | of the current test case based on the value ${True} or ${False}. Default value is ${False} |

    *Usage:*
        _Continue Keyword Execution On Failure_ <continue_on_failure>

    *Note:*
        Users can override the value set by this keyword by configuring the parameter _continue_on_failure_ with value _
        true_ or _false_ in the FW configuration file.
        The configuration file entry will have the global scope till the end of the pybot run. It can be defined in the global section in the file

    *Examples:*
    | *Keyword Name* | *continue_on_failure* |
    | Continue Keyword Execution On Failure | ${True} |

    """
    config = get_variables()
    if "continue_on_failure" in list(config.keys()):
        logger.info(
            "'continue_on_failure' is configured in configuration file, so this keyword execution will not take effect")
    else:
        KeywordUtils().continue_on_failure(continue_on_failure)
